# -*- coding: utf-8 -*-
"""
Phase: 292
Scope: Tiere & Natur, Pflanzen & Flora, Gastronomie, Technologie & Robotik -> de/en/pl

- gastro/tech nutzen die bereits _tc-gewrappten _mk*-Factories (P288).
- tiere (genTiereHL/genTiereMatchQ/genUniversalPinQ), pflanzen (genPflanzen*),
  genUniversalMatchQ werden hier mit _tc gewrappt (Prompt, Einheit, Match opts/ans).
- 162 Prompts + 36 Einheiten + 139 fixedOpts -> en+pl, indexbasiert gegen die
  exakt gleiche sortierte Extraktion (deutsche Schluessel nicht neu getippt).
Dependencies: patch_291_en_5cats.py
"""
import os, re, json

GEN = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), 'gen.py')
content = open(GEN, encoding='utf-8').read()

def rep(old, new, label, n=1):
    global content
    c = content.count(old)
    if c != n:
        print(f'[FAIL] {label}: count={c} (erwartet {n})'); raise SystemExit(1)
    content = content.replace(old, new)
    print(f'[OK]   {label} (x{c})')

# ---- Engine-Wraps ----
rep('var unit=cfg.unit||"";', 'var unit=_tc(cfg.unit||"");', 'HL unit (tiere+pflanzen)', n=2)
rep('prompt:cfg.prompt||"Welches ist mehr?"', 'prompt:_tc(cfg.prompt||"Welches ist mehr?")', 'HL prompt (tiere+pflanzen)', n=2)
rep('var prompt=cfg.prompt||"Welches Tier ist das?";', 'var prompt=_tc(cfg.prompt||"Welches Tier ist das?");', 'genTiereMatchQ prompt', n=1)
rep('var prompt=cfg.prompt||"Ordne richtig zu!";', 'var prompt=_tc(cfg.prompt||"Ordne richtig zu!");', 'genPflanzenMatchQ prompt', n=1)
rep('ans:cor.c,opts:opts,meta:"",lid:_lid,cc:"de"};', 'ans:_tc(cor.c),opts:opts.map(_tc),meta:"",lid:_lid,cc:"de"};', 'Match opts/ans (tiere+pflanzen)', n=2)
rep('prompt:storedPrompt||modeObj.prompt||t("q_uk_pin")', 'prompt:_tc(storedPrompt||modeObj.prompt)||t("q_uk_pin")', 'genUniversalPinQ prompt', n=1)
rep('prompt:modeObj.prompt||t("q_uk_match"),subj:item.n,ans:cor,opts,', 'prompt:_tc(modeObj.prompt)||t("q_uk_match"),subj:item.n,ans:_tc(cor),opts:opts.map(_tc),', 'genUniversalMatchQ prompt+opts/ans', n=1)
rep('prompt:cfg.prompt||modeObj.prompt||"Wo liegt das?",', 'prompt:_tc(cfg.prompt||modeObj.prompt||"Wo liegt das?"),', 'genPflanzenPinQ prompt', n=1)

# ---- Extraktion (identisch zur Sichtung) ----
cats = ['tiere', 'pflanzen', 'gastro', 'tech']
prompts = set(); units = set(); fopts = set()
for cat in cats:
    for t in ['pin', 'hl', 'match']:
        d = json.load(open(f'data/{cat}_{t}.json', encoding='utf-8'))
        for g, v in d.items():
            if not isinstance(v, dict): continue
            if v.get('prompt'): prompts.add(v['prompt'])
            if v.get('unit'): units.add(v['unit'])
            for o in (v.get('fixedOpts') or []): fopts.add(o)
prompts = sorted(prompts); units = sorted(units); fopts = sorted(fopts)
assert (len(prompts), len(units), len(fopts)) == (162, 36, 139), (len(prompts), len(units), len(fopts))

