EN={}; PL={}
for de,en,pl in zip(prompts,PROMPT_EN,PROMPT_PL): EN[de]=en; PL[de]=pl
for de in units:
    assert de in UNIT_EN and de in UNIT_PL, ('unit missing',de)
    EN[de]=UNIT_EN[de]; PL[de]=UNIT_PL[de]
for de in fopts:
    assert de in FIXED_EN and de in FIXED_PL, ('fopt missing',de)
    EN[de]=FIXED_EN[de]; PL[de]=FIXED_PL[de]

def block(src,name):
    a=src.index(name+'=')+len(name+'=')
    d=0;k=a;ins=None;esc=False
    while k<len(src):
        c=src[k]
        if ins:
            if esc:esc=False
            elif c=='\\':esc=True
            elif c==ins:ins=None
        else:
            if c in '"\'`':ins=c
            elif c=='{':d+=1
            elif c=='}':
                d-=1
                if d==0:k+=1;break
        k+=1
    return a,k,src[a:k]

s_idx,e_idx,obj=block(content,'const _CONTENT_I18N')
data=json.loads(obj)
data.setdefault('en',{}).update(EN)
data.setdefault('pl',{}).update(PL)
content=content[:s_idx]+json.dumps(data,ensure_ascii=False)+content[e_idx:]
print(f'[OK]   _CONTENT_I18N += {len(EN)} en / {len(PL)} pl (tiere/pflanzen/gastro/tech)')

_tmp=GEN+'.tmp'
open(_tmp,'w',encoding='utf-8').write(content)
os.replace(_tmp,GEN)
print('\nPatch complete.')
